var i=`0601-couscous-with-seven-vegetables`;var n=`world-0601`;var s=`MA`;var a=`northern-africa`;var o=4;var r=71;var g={en:`Couscous with Seven Vegetables`,ua:`Кускус із сімома овочами`};var u={en:`Couscous with Seven Vegetables is a Morocco classic prepared with yellow onion, tomato, chicken thigh, carrot. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Кускус із сімома овочами, страва кухні країни Марокко зі складниками: жовта цибуля, помідор, куряче стегно, морква. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var l=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`yellow-onion`,170,`g`],[`extra-virgin-olive-oil`,45,`ml`],[`tomato`,180,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 28 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 28 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:28,i:[[`chicken-thigh`,550,`g`],[`water`,1050,`ml`],[`carrot`,230,`g`],[`turnip`,180,`g`],[`white-cabbage`,220,`g`],[`ground-ginger`,4,`g`],[`ground-turmeric`,4,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 17 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 17 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:17,i:[[`zucchini`,210,`g`],[`pumpkin`,220,`g`],[`canned-chickpeas`,220,`g`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]},{en:`Fluff dry couscous with some warm water; steam it over the vegetable broth until tender, separating grains with a fork.`,ua:`Зволожте сухий кускус теплою водою й пропарте над овочевим бульйоном до м’якості, розпушуючи зерна виделкою.`,t:[`couscous-steaming`],m:12,i:[[`couscous`,340,`g`],[`water`,410,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`parsley`,20,`g`]]}];var h={slug:i,id:n,country:`MA`,region:a,servings:4,minutes:71,title:g,text:u,steps:l};export{s as country,h as default,n as id,r as minutes,a as region,o as servings,i as slug,l as steps,u as text,g as title};